 private static Result read(byte[] d,int pos,int depth)throws IOException{if(depth>20||pos>=d.length)throw new IOException("CBOR EOF");int b=d[pos++]&255,intype=b>>5,ai=b&31;if(intype==7){if(ai==20)return new Result(false,pos);if(ai==21)return new Result(true,pos);if(ai==22)return new Result(null,pos);throw new IOException("Unsupported simple");}if(ai==31)throw new IOException("Indefinite CBOR unsupported");int bytes=ai<24?0:ai==24?1:ai==25?2:ai==26?4:ai==27?8:-1;if(bytes<0||pos+bytes>d.length)throw new IOException("Invalid length");if(bytes==8&&(d[pos]&128)!=0)throw new IOException("Unsupported unsigned integer");long n=ai<24?ai:0;for(int i=0;i<bytes;i++)n=(n<<8)|(d[pos++]&255);if((bytes==1&&n<24)||(bytes==2&&n<256)||(bytes==4&&n<65536)||(bytes==8&&n<4294967296L))throw new IOException("Nonminimal CBOR");if(intype==0||intype==1)return new Result(intype==0?n:-1-n,pos);if(n>1000000)throw new IOException("Oversize");int len=(int)n;if(intype==2||intype==3){if(pos+len>d.length)throw new IOException("Truncated");byte[] v=Arrays.copyOfRange(d,pos,pos+len);return new Result(intype==2?v:StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(v)).toString(),pos+len);}if(intype==4){List<Object> l=new ArrayList<>();for(int i=0;i<len;i++){Result r=read(d,pos,depth+1);pos=r.next;l.add(r.value);}return new Result(l,pos);}if(intype==5){Map<Object,Object> m=new LinkedHashMap<>();byte[] previous=null;for(int i=0;i<len;i++){int start=pos;Result k=read(d,pos,depth+1);byte[] encoded=Arrays.copyOfRange(d,start,k.next);if(previous!=null&&compare(previous,encoded)>=0)throw new IOException("Duplicate or noncanonical CBOR map key");Result v=read(d,k.next,depth+1);pos=v.next;m.put(k.value,v.value);previous=encoded;}return new Result(m,pos);}throw new IOException("Unsupported major type");}
